function cheapestClimb(cost: number[]): number {
  const best = (i: number): number => (i < 2 ? cost[i] : cost[i] + Math.min(best(i - 1), best(i - 2)));
  const n = cost.length;
  return Math.min(best(n - 1), best(n - 2));
}

